elif len(psu_years) > 1:
    # Multiple entries, need to find the range
    all_years = []
    for year_str in psu_years:
        if '–' in year_str:
            start_year, end_year = year_str.split('–')
            if end_year == '' or end_year == ' ':
                all_years.append(int(start_year))
            else:
                all_years.extend([int(start_year), int(end_year)])
        else:
            all_years.append(int(year_str))

    min_year = min(all_years)
    max_year = max(all_years)
    duration = max_year - min_year
